css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .52); position: relative; }
.loader .limb { position: absolute; left: 6%; right: 6%; top: 26%; height: 44%; border-radius: 999px; background: linear-gradient(color-mix(in srgb, #fff 25%, var(--accent)), var(--accent)); }
.loader span { position: absolute; top: 20%; width: 13%; height: 56%; border-radius: 4px; background: var(--accent-2); box-shadow: inset -2px 0 0 color-mix(in srgb, #000 12%, transparent); transform-origin: 50% 50%; transform: scaleX(0) skewX(-14deg); animation: wrap-turn calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader span:nth-of-type(1) { left: 10%; }
.loader span:nth-of-type(2) { left: 24%; animation-delay: calc(var(--loader-speed) * .22); }
.loader span:nth-of-type(3) { left: 38%; animation-delay: calc(var(--loader-speed) * .44); }
.loader span:nth-of-type(4) { left: 52%; animation-delay: calc(var(--loader-speed) * .66); }
.loader span:nth-of-type(5) { left: 66%; animation-delay: calc(var(--loader-speed) * .88); }
.loader .roll { position: absolute; top: 20%; left: 76%; width: 22%; height: 42%; border-radius: 50%; background: radial-gradient(circle at 42% 36%, var(--accent-2), color-mix(in srgb, #000 14%, var(--accent-2))); box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 30%, transparent); animation: wrap-roll calc(var(--loader-speed) * 3) linear infinite; }
@keyframes wrap-turn { 0%, 6% { transform: scaleX(0) skewX(-14deg); opacity: 0; } 24%, 74% { transform: scaleX(1) skewX(-14deg); opacity: 1; } 92%, 100% { transform: scaleX(0) skewX(-14deg); opacity: 0; } }
@keyframes wrap-roll { to { transform: rotate(1turn); } }
